"""
Base framework for Z3-based verification toolkit.

Provides common utilities for graph representation, transition system
encoding, and experiment result reporting.
"""

from .graphs import Graph, PETERSEN_GRAPH, DIAMOND_DAG, CYCLIC_GRAPH_6
from .transition_systems import TransitionSystem
from .reporter import report_result, run_experiments
"""Graph data structures and benchmark graphs."""


class Graph:
    """Simple directed/undirected graph."""

    def __init__(self, nodes, edges, directed=False):
        self.nodes = list(nodes)
        self.edges = list(edges)
        self.directed = directed
        self._adj = {}
        for n in self.nodes:
            self._adj[n] = []
        for u, v in self.edges:
            self._adj[u].append(v)
            if not directed:
                self._adj[v].append(u)

    def neighbors(self, node):
        return self._adj.get(node, [])

    def num_nodes(self):
        return len(self.nodes)

    def num_edges(self):
        return len(self.edges)


PETERSEN_GRAPH = Graph(
